"""invclass.py q GROUP: dimension (and a basis) of H^1(H(q); Z2)^K, K generated by GROUP (see ksym.py), computed in
the fundamental-cycle basis of a BFS spanning tree: a class = holonomies c(e) on the q^6 fundamental cycles C_e;
k^*c(e) = sum of c over the non-tree edges of k(C_e). Writes each basis class as a DM solution file (nu = 1 on the
non-tree edges where the class is 1, 0 on the tree: a cocycle representing it) and scores Condition A."""
import sys, random
from collections import deque
sys.path.insert(0, '.')
import dmio, ksym

q, kind = int(sys.argv[1]), sys.argv[2]
H = dmio.load(q); N, Q1 = H.N, q + 1; V = 2 * N
P = ksym.perms(H, ksym.gens(q, kind))
assert P is not None
# graph: vertex ids points 0..N-1, lines N..2N-1; flag index l*Q1+k
adj = [[] for _ in range(V)]
for l, L in enumerate(H.lines):
    for k, p in enumerate(L):
        f = l * Q1 + k
        adj[p].append((N + l, f)); adj[N + l].append((p, f))
fpos = {}
for l, L in enumerate(H.lines):
    for k, p in enumerate(L): fpos[(p, l)] = l * Q1 + k
F = N * Q1
# BFS tree
par = [-1] * V; pf = [-1] * V; seen = [False] * V; seen[0] = True; dq = deque([0]); tree = [False] * F
order = []
while dq:
    x = dq.popleft(); order.append(x)
    for y, f in adj[x]:
        if not seen[y]:
            seen[y] = True; par[y] = x; pf[y] = f; tree[f] = True; dq.append(y)
nontree = [f for f in range(F) if not tree[f]]
nidx = {f: i for i, f in enumerate(nontree)}
D = len(nontree)
print('q', q, 'K', kind, 'cohomology dimension', D, '(q^6 =', q ** 6, ')')
def path_to_root(x):
    s = set()
    while par[x] >= 0:
        s ^= {pf[x]}; x = par[x]
    return s
fl_end = [None] * F
for l, L in enumerate(H.lines):
    for k, p in enumerate(L): fl_end[l * Q1 + k] = (p, N + l)
root_path = [path_to_root(x) for x in range(V)]
def cycle(f):
    a, b = fl_end[f]
    return root_path[a] ^ root_path[b] ^ {f}
cycles = [cycle(f) for f in nontree]
rows = []
for pp, lp in P:
    def img(f):
        a, b = fl_end[f]
        return fpos[(pp[a], lp[b - N])]
    for i, f in enumerate(nontree):
        cyc = {img(g) for g in cycles[i]}
        r = 1 << i
        for g in cyc:
            if not tree[g]: r ^= 1 << nidx[g]
        rows.append(r)
# nullspace of the row system over GF(2): reduce rows to echelon form, then nullspace
piv = {}
for r in rows:
    while r:
        h = r.bit_length() - 1
        if h in piv: r ^= piv[h]
        else: piv[h] = r; break
rank = len(piv)
print('rank', rank, 'invariant classes dimension', D - rank)
# basis of nullspace: free variables = non-pivot columns
# back-substitute: make reduced echelon
keys = sorted(piv)
for h in keys:
    r = piv[h]
    for h2 in keys:
        if h2 != h and (piv[h2] >> h) & 1: piv[h2] ^= r
free = [i for i in range(D) if i not in piv]
basis = []
for fr in free[:16]:
    c = 1 << fr
    for h, r in piv.items():
        if (r >> fr) & 1: c |= 1 << h
    basis.append(c)
print('basis vectors (up to 16):', len(basis))
for bi, c in enumerate(basis):
    nu = [0] * F
    for i, f in enumerate(nontree):
        if (c >> i) & 1: nu[f] = 1
    path = f'runs/inv_{kind}_q{q}_b{bi}.sol'
    dmio.write_dm(H, nu, path)
    print(' class', bi, 'weight', bin(c).count('1'), 'Condition-A failures', dmio.score_condA(H, path))
